-- Limites macro de congregações exibidos apenas como referência no mapa.
-- Esta tabela é independente de territorios e enderecos: nenhum vínculo existente é alterado.

create table if not exists public.limites_congregacoes (
  id bigint generated by default as identity primary key,
  nome text not null,
  numero text,
  idioma text not null,
  tipo text not null default 'Território de congregação',
  coordenadas jsonb not null,
  cor text not null default '#2563eb',
  atualizado_origem_em date,
  importado_em timestamptz not null default now(),
  ativo boolean not null default true,
  constraint limites_congregacoes_numero_unique unique (numero),
  constraint limites_congregacoes_coordenadas_array
    check (jsonb_typeof(coordenadas) = 'array')
);

comment on table public.limites_congregacoes is
  'Polígonos macro usados somente como camada visual de referência no mapa.';

alter table public.limites_congregacoes enable row level security;

revoke select on public.limites_congregacoes from anon;
grant select on public.limites_congregacoes to authenticated;
grant insert, update, delete on public.limites_congregacoes to authenticated;
grant usage, select on sequence public.limites_congregacoes_id_seq to authenticated;

drop policy if exists "Limites ativos podem ser visualizados" on public.limites_congregacoes;
create policy "Limites ativos podem ser visualizados"
on public.limites_congregacoes
for select
to authenticated
using (ativo = true);

drop policy if exists "Superadmin administra limites" on public.limites_congregacoes;
create policy "Superadmin administra limites"
on public.limites_congregacoes
for all
to authenticated
using (
  exists (
    select 1
    from public.usuarios_app usuario
    where usuario.auth_user_id = auth.uid()
      and usuario.ativo = true
      and usuario.papel = 'superadmin'
  )
)
with check (
  exists (
    select 1
    from public.usuarios_app usuario
    where usuario.auth_user_id = auth.uid()
      and usuario.ativo = true
      and usuario.papel = 'superadmin'
  )
);

insert into public.limites_congregacoes (
  nome,
  numero,
  idioma,
  tipo,
  coordenadas,
  cor,
  atualizado_origem_em,
  ativo
)
